import foodDatabase from '../data/food-database.json';

export class FoodDatabase {
  constructor() {
    this.foods = foodDatabase.foods;
    this.categories = foodDatabase.categories;
  }

  // Search foods by name, keywords, or category
  search(query, options = {}) {
    if (!query) return this.getCommonFoods();
    
    const {
      category = null,
      limit = 20,
      exactMatch = false
    } = options;

    const searchTerm = query.toLowerCase();
    
    let results = this.foods.filter(food => {
      // Category filter
      if (category && food.category !== category) return false;
      
      // Search in name
      const nameMatch = exactMatch 
        ? food.name.toLowerCase() === searchTerm
        : food.name.toLowerCase().includes(searchTerm);
      
      // Search in keywords
      const keywordMatch = food.keywords && food.keywords.some(keyword => 
        exactMatch 
          ? keyword.toLowerCase() === searchTerm
          : keyword.toLowerCase().includes(searchTerm)
      );
      
      // Search in brand
      const brandMatch = food.brand && food.brand.toLowerCase().includes(searchTerm);
      
      return nameMatch || keywordMatch || brandMatch;
    });

    // Sort by relevance (exact matches first, then by name)
    results.sort((a, b) => {
      const aExact = a.name.toLowerCase() === searchTerm;
      const bExact = b.name.toLowerCase() === searchTerm;
      
      if (aExact && !bExact) return -1;
      if (!aExact && bExact) return 1;
      
      return a.name.localeCompare(b.name);
    });

    return results.slice(0, limit);
  }

  // Get foods by category
  getByCategory(category, limit = 20) {
    return this.foods
      .filter(food => food.category === category)
      .slice(0, limit);
  }

  // Get all foods
  getAllFoods() {
    return this.foods;
  }

  // Get most common foods
  getCommonFoods(limit = 20) {
    return this.foods
      .filter(food => food.common)
      .slice(0, limit);
  }

  // Get food by ID
  getById(id) {
    return this.foods.find(food => food.id === id);
  }

  // Get all categories
  getCategories() {
    return this.categories;
  }

  // Add custom food to the database (for user additions)
  addCustomFood(foodData) {
    const customFood = {
      ...foodData,
      id: `custom_${Date.now()}`,
      brand: foodData.brand || 'Custom',
      common: false,
      keywords: foodData.keywords || [foodData.name.toLowerCase()]
    };
    
    this.foods.push(customFood);
    return customFood;
  }

  // Get nutrition summary for a food item
  getNutritionSummary(food, servingMultiplier = 1) {
    return {
      calories: Math.round(food.calories * servingMultiplier),
      protein: Math.round(food.protein * servingMultiplier * 10) / 10,
      carbs: Math.round(food.carbs * servingMultiplier * 10) / 10,
      fat: Math.round(food.fat * servingMultiplier * 10) / 10,
      fiber: Math.round(food.fiber * servingMultiplier * 10) / 10,
      sugar: Math.round(food.sugar * servingMultiplier * 10) / 10,
      sodium: Math.round(food.sodium * servingMultiplier),
      serving_size: food.serving_size
    };
  }

  // Get foods that match partial barcode
  getByBarcode(barcode) {
    return this.foods.filter(food => food.barcode === barcode);
  }

  // Get random popular foods for suggestions
  getRandomSuggestions(count = 5) {
    const commonFoods = this.getCommonFoods();
    const shuffled = [...commonFoods].sort(() => 0.5 - Math.random());
    return shuffled.slice(0, count);
  }

  // Calculate nutrition density (nutrition per calorie)
  getNutritionDensity(food) {
    if (food.calories === 0) return 0;
    
    return {
      protein_density: (food.protein * 4) / food.calories, // protein calories / total calories
      fiber_density: food.fiber / food.calories * 100, // fiber per calorie
      nutrient_score: (food.protein + food.fiber) / food.calories * 100
    };
  }

  // Export user's custom foods
  exportCustomFoods() {
    return this.foods.filter(food => food.id.startsWith('custom_'));
  }

  // Import custom foods
  importCustomFoods(customFoods) {
    customFoods.forEach(food => {
      if (!this.getById(food.id)) {
        this.foods.push(food);
      }
    });
  }
}

// Create singleton instance
export const foodDB = new FoodDatabase();

// Helper functions for React components
export const searchFoods = (query, options) => foodDB.search(query, options);
export const getFoodById = (id) => foodDB.getById(id);
export const getCommonFoods = (limit) => foodDB.getCommonFoods(limit);
export const getAllFoods = () => foodDB.getAllFoods();
export const getFoodCategories = () => foodDB.getCategories();
export const addCustomFood = (foodData) => foodDB.addCustomFood(foodData);
export const getNutritionSummary = (food, multiplier) => foodDB.getNutritionSummary(food, multiplier);

export default foodDB;