import React, { useState, useRef, useCallback, useEffect } from 'react';
import { Camera, X, RotateCcw, Check, Zap, Info, AlertCircle } from 'lucide-react';

const PhotoCapture = ({ onPhotoTaken, onClose, isVisible }) => {
    const [stream, setStream] = useState(null);
    const [photo, setPhoto] = useState(null);
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState(null);
    const [facingMode, setFacingMode] = useState('environment'); // 'user' for front, 'environment' for back
    const [analysisPrompts, setAnalysisPrompts] = useState([]);
    
    const videoRef = useRef(null);
    const canvasRef = useRef(null);

    // Camera access
    const startCamera = useCallback(async () => {
        setIsLoading(true);
        setError(null);
        
        try {
            // Request camera permission
            const constraints = {
                video: {
                    facingMode: facingMode,
                    width: { ideal: 1280 },
                    height: { ideal: 720 },
                    aspectRatio: { ideal: 16/9 }
                },
                audio: false
            };

            const mediaStream = await navigator.mediaDevices.getUserMedia(constraints);
            setStream(mediaStream);
            
            if (videoRef.current) {
                videoRef.current.srcObject = mediaStream;
            }
        } catch (err) {
            console.error('Camera access error:', err);
            setError(getErrorMessage(err));
        } finally {
            setIsLoading(false);
        }
    }, [facingMode]);

    const getErrorMessage = (err) => {
        if (err.name === 'NotAllowedError') {
            return 'Camera permission denied. Please allow camera access in your browser settings.';
        } else if (err.name === 'NotFoundError') {
            return 'No camera found on this device.';
        } else if (err.name === 'NotSupportedError') {
            return 'Camera is not supported on this device.';
        }
        return 'Unable to access camera. Please try again.';
    };

    // Stop camera
    const stopCamera = useCallback(() => {
        if (stream) {
            stream.getTracks().forEach(track => track.stop());
            setStream(null);
        }
    }, [stream]);

    // Take photo
    const takePhoto = useCallback(() => {
        if (videoRef.current && canvasRef.current) {
            const video = videoRef.current;
            const canvas = canvasRef.current;
            const context = canvas.getContext('2d');
            
            // Set canvas dimensions to match video
            canvas.width = video.videoWidth;
            canvas.height = video.videoHeight;
            
            // Draw video frame to canvas
            context.drawImage(video, 0, 0, canvas.width, canvas.height);
            
            // Convert to blob
            canvas.toBlob((blob) => {
                const imageUrl = URL.createObjectURL(blob);
                setPhoto({
                    blob,
                    url: imageUrl,
                    width: canvas.width,
                    height: canvas.height
                });
                
                // Generate analysis prompts
                generateAnalysisPrompts();
                
                // Stop camera after taking photo
                stopCamera();
            }, 'image/jpeg', 0.8);
        }
    }, [stopCamera]);

    // Switch camera (front/back)
    const switchCamera = useCallback(() => {
        setFacingMode(prev => prev === 'user' ? 'environment' : 'user');
    }, []);

    // Generate AI-style analysis prompts
    const generateAnalysisPrompts = () => {
        const prompts = [
            {
                icon: '🍎',
                text: 'Does this look like a fruit or vegetable?',
                category: 'type'
            },
            {
                icon: '🍞',
                text: 'Is this a grain or bread product?',
                category: 'grain'
            },
            {
                icon: '🥩',
                text: 'Can you identify any protein sources?',
                category: 'protein'
            },
            {
                icon: '📏',
                text: 'Estimate the portion size compared to your hand',
                category: 'portion'
            },
            {
                icon: '🏷️',
                text: 'Look for nutrition labels or packaging',
                category: 'label'
            },
            {
                icon: '🔍',
                text: 'Count the number of different foods visible',
                category: 'count'
            }
        ];
        
        // Randomly select 3-4 prompts
        const shuffled = prompts.sort(() => 0.5 - Math.random());
        setAnalysisPrompts(shuffled.slice(0, Math.min(4, shuffled.length)));
    };

    // Confirm photo and pass to parent
    const confirmPhoto = () => {
        if (photo) {
            onPhotoTaken(photo, analysisPrompts);
            cleanup();
        }
    };

    // Retake photo
    const retakePhoto = () => {
        if (photo) {
            URL.revokeObjectURL(photo.url);
            setPhoto(null);
            setAnalysisPrompts([]);
            startCamera();
        }
    };

    // Cleanup
    const cleanup = useCallback(() => {
        stopCamera();
        if (photo) {
            URL.revokeObjectURL(photo.url);
            setPhoto(null);
        }
        setAnalysisPrompts([]);
        setError(null);
    }, [stopCamera, photo]);

    // Effects
    useEffect(() => {
        if (isVisible && !photo) {
            startCamera();
        }
        
        return () => {
            cleanup();
        };
    }, [isVisible, photo, startCamera, cleanup]);

    useEffect(() => {
        if (facingMode && stream) {
            stopCamera();
            startCamera();
        }
    }, [facingMode, startCamera, stopCamera, stream]);

    if (!isVisible) return null;

    return (
        <div className="fixed inset-0 bg-black z-50 flex flex-col">
            {/* Header */}
            <div className="flex justify-between items-center p-4 bg-black/50 text-white">
                <button 
                    onClick={onClose}
                    className="p-2 rounded-full bg-black/30 hover:bg-black/50 transition"
                >
                    <X className="w-6 h-6" />
                </button>
                <h2 className="text-lg font-semibold">Take Food Photo</h2>
                <div className="w-10"></div>
            </div>

            {/* Camera/Photo View */}
            <div className="flex-1 relative">
                {error ? (
                    <div className="flex-1 flex items-center justify-center p-6">
                        <div className="bg-red-50 dark:bg-red-900/20 p-6 rounded-xl max-w-sm mx-auto text-center">
                            <AlertCircle className="w-12 h-12 text-red-500 mx-auto mb-4" />
                            <h3 className="font-semibold text-red-800 dark:text-red-200 mb-2">Camera Error</h3>
                            <p className="text-red-600 dark:text-red-300 text-sm mb-4">{error}</p>
                            <button 
                                onClick={startCamera}
                                className="bg-red-600 text-white px-4 py-2 rounded-lg hover:bg-red-700 transition"
                            >
                                Try Again
                            </button>
                        </div>
                    </div>
                ) : photo ? (
                    // Photo preview
                    <div className="flex-1 flex flex-col">
                        <div className="flex-1 flex items-center justify-center bg-black">
                            <img 
                                src={photo.url} 
                                alt="Captured food" 
                                className="max-w-full max-h-full object-contain"
                            />
                        </div>
                        
                        {/* Analysis Prompts */}
                        <div className="bg-white dark:bg-gray-800 p-4 max-h-48 overflow-y-auto">
                            <div className="flex items-center gap-2 mb-3">
                                <Info className="w-5 h-5 text-blue-500" />
                                <h3 className="font-semibold text-gray-800 dark:text-gray-200">Photo Analysis Tips</h3>
                            </div>
                            <div className="space-y-2">
                                {analysisPrompts.map((prompt, index) => (
                                    <div key={index} className="flex items-center gap-3 p-2 bg-gray-50 dark:bg-gray-700 rounded-lg">
                                        <span className="text-lg">{prompt.icon}</span>
                                        <span className="text-sm text-gray-700 dark:text-gray-300">{prompt.text}</span>
                                    </div>
                                ))}
                            </div>
                        </div>
                    </div>
                ) : (
                    // Camera view
                    <div className="flex-1 relative">
                        {isLoading ? (
                            <div className="flex-1 flex items-center justify-center">
                                <div className="text-white text-center">
                                    <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-white mx-auto mb-4"></div>
                                    <p>Starting camera...</p>
                                </div>
                            </div>
                        ) : (
                            <>
                                <video
                                    ref={videoRef}
                                    autoPlay
                                    playsInline
                                    muted
                                    className="w-full h-full object-cover"
                                />
                                
                                {/* Camera overlay */}
                                <div className="absolute inset-0 pointer-events-none">
                                    {/* Viewfinder */}
                                    <div className="absolute inset-0 flex items-center justify-center">
                                        <div className="w-64 h-64 border-2 border-white/50 rounded-lg"></div>
                                    </div>
                                    
                                    {/* Helper text */}
                                    <div className="absolute top-4 left-4 right-4">
                                        <div className="bg-black/50 text-white p-3 rounded-lg text-center">
                                            <p className="text-sm">Position the food item in the frame</p>
                                        </div>
                                    </div>
                                </div>
                            </>
                        )}
                    </div>
                )}

                {/* Hidden canvas for photo capture */}
                <canvas ref={canvasRef} className="hidden" />
            </div>

            {/* Controls */}
            <div className="bg-black/50 p-4">
                {photo ? (
                    // Photo controls
                    <div className="flex justify-center gap-6">
                        <button 
                            onClick={retakePhoto}
                            className="flex flex-col items-center gap-2 p-3 rounded-full bg-gray-600 hover:bg-gray-700 transition text-white"
                        >
                            <RotateCcw className="w-6 h-6" />
                            <span className="text-xs">Retake</span>
                        </button>
                        <button 
                            onClick={confirmPhoto}
                            className="flex flex-col items-center gap-2 p-3 rounded-full bg-green-600 hover:bg-green-700 transition text-white"
                        >
                            <Check className="w-6 h-6" />
                            <span className="text-xs">Use Photo</span>
                        </button>
                    </div>
                ) : (
                    // Camera controls
                    <div className="flex justify-between items-center">
                        <div className="w-16"></div>
                        
                        <button 
                            onClick={takePhoto}
                            disabled={isLoading || error}
                            className="w-16 h-16 rounded-full bg-white border-4 border-gray-300 hover:bg-gray-100 transition disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center"
                        >
                            <Camera className="w-8 h-8 text-gray-700" />
                        </button>
                        
                        <button 
                            onClick={switchCamera}
                            disabled={isLoading || error}
                            className="p-3 rounded-full bg-black/30 hover:bg-black/50 transition text-white disabled:opacity-50 disabled:cursor-not-allowed"
                        >
                            <RotateCcw className="w-6 h-6" />
                        </button>
                    </div>
                )}
            </div>
        </div>
    );
};

export default PhotoCapture;