import React, { useEffect, useRef, useState } from 'react';
import { BarChart3, PieChart, TrendingUp, Clock, Download, Upload } from 'lucide-react';

const DataVisualization = ({ 
    dailyLogs = {}, 
    mlData = { eatingPatterns: [], timingPreferences: {}, mealCategoryHistory: [] },
    foodDatabase = [],
    quickAdds = []
}) => {
    const [activeChart, setActiveChart] = useState('calories');
    
    // Canvas refs
    const calorieChartRef = useRef(null);
    const timingChartRef = useRef(null);
    const macroChartRef = useRef(null);
    const accuracyChartRef = useRef(null);
    const timelineChartRef = useRef(null);
    const usageChartRef = useRef(null);

    const colors = {
        primary: '#667eea',
        secondary: '#764ba2',
        success: '#4ade80',
        warning: '#fbbf24',
        danger: '#ef4444',
        info: '#3b82f6',
        breakfast: '#fbbf24',
        lunch: '#4ade80', 
        dinner: '#ef4444',
        snacks: '#8b5cf6'
    };

    // Calculate statistics
    const stats = React.useMemo(() => {
        const totalLogs = Object.values(dailyLogs).flat().length;
        const totalCalories = Object.values(dailyLogs).flat().reduce((sum, meal) => sum + (meal.calories || 0), 0);
        const avgCaloriesPerDay = totalLogs > 0 ? Math.round(totalCalories / Object.keys(dailyLogs).length) : 0;
        const accuracy = mlData.mealCategoryHistory.length > 0 ? 
            Math.round((mlData.mealCategoryHistory.filter(h => h.category === h.suggestedCategory).length / mlData.mealCategoryHistory.length) * 100) : 0;
        
        return {
            totalLogs,
            avgCaloriesPerDay,
            accuracy,
            daysTracked: Object.keys(dailyLogs).length
        };
    }, [dailyLogs, mlData]);

    // Chart drawing functions
    const drawCalorieChart = () => {
        const canvas = calorieChartRef.current;
        if (!canvas) return;
        
        const ctx = canvas.getContext('2d');
        const rect = canvas.getBoundingClientRect();
        canvas.width = rect.width * 2;
        canvas.height = rect.height * 2;
        ctx.scale(2, 2);
        
        // Clear canvas
        ctx.clearRect(0, 0, rect.width, rect.height);
        
        const data = Object.entries(dailyLogs)
            .sort(([a], [b]) => new Date(a) - new Date(b))
            .slice(-14) // Last 14 days
            .map(([date, meals]) => ({
                date: new Date(date).toLocaleDateString('en-US', { month: 'short', day: 'numeric' }),
                calories: meals.reduce((sum, meal) => sum + (meal.calories || 0), 0)
            }));
        
        if (data.length === 0) {
            ctx.fillStyle = '#666';
            ctx.font = '16px sans-serif';
            ctx.textAlign = 'center';
            ctx.fillText('No data available', rect.width / 2, rect.height / 2);
            return;
        }
        
        const maxCalories = Math.max(...data.map(d => d.calories));
        const padding = 40;
        const chartWidth = rect.width - (padding * 2);
        const chartHeight = rect.height - (padding * 2);
        
        // Draw grid lines
        ctx.strokeStyle = '#e5e7eb';
        ctx.lineWidth = 1;
        for (let i = 0; i <= 5; i++) {
            const y = padding + (chartHeight / 5) * i;
            ctx.beginPath();
            ctx.moveTo(padding, y);
            ctx.lineTo(padding + chartWidth, y);
            ctx.stroke();
        }
        
        // Draw line chart
        ctx.strokeStyle = colors.primary;
        ctx.lineWidth = 3;
        ctx.beginPath();
        
        data.forEach((point, index) => {
            const x = padding + (chartWidth / Math.max(data.length - 1, 1)) * index;
            const y = padding + chartHeight - (point.calories / Math.max(maxCalories, 1)) * chartHeight;
            
            if (index === 0) {
                ctx.moveTo(x, y);
            } else {
                ctx.lineTo(x, y);
            }
            
            // Draw points
            ctx.fillStyle = colors.primary;
            ctx.beginPath();
            ctx.arc(x, y, 4, 0, 2 * Math.PI);
            ctx.fill();
        });
        ctx.stroke();
        
        // Draw labels
        ctx.fillStyle = '#374151';
        ctx.font = '12px sans-serif';
        ctx.textAlign = 'center';
        data.forEach((point, index) => {
            if (data.length <= 7 || index % Math.ceil(data.length / 5) === 0) {
                const x = padding + (chartWidth / Math.max(data.length - 1, 1)) * index;
                ctx.fillText(point.date, x, rect.height - 10);
            }
        });
        
        // Y-axis labels
        ctx.textAlign = 'right';
        for (let i = 0; i <= 5; i++) {
            const value = Math.round((maxCalories / 5) * (5 - i));
            const y = padding + (chartHeight / 5) * i;
            ctx.fillText(value.toString(), padding - 10, y + 4);
        }
    };

    const drawTimingChart = () => {
        const canvas = timingChartRef.current;
        if (!canvas) return;
        
        const ctx = canvas.getContext('2d');
        const rect = canvas.getBoundingClientRect();
        canvas.width = rect.width * 2;
        canvas.height = rect.height * 2;
        ctx.scale(2, 2);
        
        ctx.clearRect(0, 0, rect.width, rect.height);
        
        const timingData = {};
        mlData.eatingPatterns.forEach(pattern => {
            const hour = pattern.actualTimeOfDay;
            const category = pattern.mealCategory;
            if (!timingData[hour]) timingData[hour] = { breakfast: 0, lunch: 0, dinner: 0, snacks: 0 };
            timingData[hour][category]++;
        });
        
        const hours = Array.from({length: 24}, (_, i) => i);
        const maxCount = Math.max(1, ...hours.map(h => 
            Object.values(timingData[h] || {}).reduce((sum, count) => sum + count, 0)
        ));
        
        const padding = 40;
        const barWidth = (rect.width - padding * 2) / 24;
        const chartHeight = rect.height - padding * 2;
        
        // Draw stacked bars
        hours.forEach(hour => {
            const data = timingData[hour] || { breakfast: 0, lunch: 0, dinner: 0, snacks: 0 };
            const x = padding + hour * barWidth;
            let y = padding + chartHeight;
            
            Object.entries(data).forEach(([category, count]) => {
                if (count > 0) {
                    const barHeight = (count / maxCount) * chartHeight;
                    ctx.fillStyle = colors[category];
                    ctx.fillRect(x, y - barHeight, barWidth - 2, barHeight);
                    y -= barHeight;
                }
            });
            
            // Hour labels
            if (hour % 4 === 0) {
                ctx.fillStyle = '#374151';
                ctx.font = '10px sans-serif';
                ctx.textAlign = 'center';
                ctx.fillText(hour + ':00', x + barWidth/2, rect.height - 10);
            }
        });
    };

    const drawMacroChart = () => {
        const canvas = macroChartRef.current;
        if (!canvas) return;
        
        const ctx = canvas.getContext('2d');
        const rect = canvas.getBoundingClientRect();
        canvas.width = rect.width * 2;
        canvas.height = rect.height * 2;
        ctx.scale(2, 2);
        
        ctx.clearRect(0, 0, rect.width, rect.height);
        
        const totals = Object.values(dailyLogs).flat().reduce((acc, meal) => ({
            protein: acc.protein + (meal.protein || 0),
            carbs: acc.carbs + (meal.carbs || 0),
            fat: acc.fat + (meal.fat || 0)
        }), { protein: 0, carbs: 0, fat: 0 });
        
        const total = totals.protein + totals.carbs + totals.fat;
        if (total === 0) {
            ctx.fillStyle = '#666';
            ctx.font = '16px sans-serif';
            ctx.textAlign = 'center';
            ctx.fillText('No macro data', rect.width / 2, rect.height / 2);
            return;
        }
        
        const centerX = rect.width / 2;
        const centerY = rect.height / 2;
        const radius = Math.min(centerX, centerY) - 20;
        
        let startAngle = 0;
        const macroColors = { protein: '#ef4444', carbs: '#3b82f6', fat: '#fbbf24' };
        
        Object.entries(totals).forEach(([macro, value]) => {
            const sliceAngle = (value / total) * 2 * Math.PI;
            
            ctx.fillStyle = macroColors[macro];
            ctx.beginPath();
            ctx.moveTo(centerX, centerY);
            ctx.arc(centerX, centerY, radius, startAngle, startAngle + sliceAngle);
            ctx.closePath();
            ctx.fill();
            
            // Labels
            if (sliceAngle > 0.2) { // Only show label if slice is big enough
                const labelAngle = startAngle + sliceAngle / 2;
                const labelX = centerX + Math.cos(labelAngle) * (radius * 0.7);
                const labelY = centerY + Math.sin(labelAngle) * (radius * 0.7);
                
                ctx.fillStyle = 'white';
                ctx.font = 'bold 14px sans-serif';
                ctx.textAlign = 'center';
                ctx.fillText(`${Math.round((value / total) * 100)}%`, labelX, labelY);
            }
            
            startAngle += sliceAngle;
        });
    };

    const drawAccuracyChart = () => {
        const canvas = accuracyChartRef.current;
        if (!canvas) return;
        
        const ctx = canvas.getContext('2d');
        const rect = canvas.getBoundingClientRect();
        canvas.width = rect.width * 2;
        canvas.height = rect.height * 2;
        ctx.scale(2, 2);
        
        ctx.clearRect(0, 0, rect.width, rect.height);
        
        const correct = mlData.mealCategoryHistory.filter(h => h.category === h.suggestedCategory).length;
        const total = mlData.mealCategoryHistory.length;
        const accuracy = total > 0 ? correct / total : 0;
        
        const centerX = rect.width / 2;
        const centerY = rect.height / 2;
        const radius = Math.min(centerX, centerY) - 30;
        
        // Background circle
        ctx.fillStyle = '#e5e7eb';
        ctx.beginPath();
        ctx.arc(centerX, centerY, radius, 0, 2 * Math.PI);
        ctx.fill();
        
        // Accuracy arc
        ctx.fillStyle = colors.success;
        ctx.beginPath();
        ctx.moveTo(centerX, centerY);
        ctx.arc(centerX, centerY, radius, -Math.PI / 2, (-Math.PI / 2) + (accuracy * 2 * Math.PI));
        ctx.closePath();
        ctx.fill();
        
        // Center text
        ctx.fillStyle = '#1f2937';
        ctx.font = 'bold 24px sans-serif';
        ctx.textAlign = 'center';
        ctx.fillText(`${Math.round(accuracy * 100)}%`, centerX, centerY + 8);
        
        ctx.font = '12px sans-serif';
        ctx.fillText(`${correct}/${total} predictions`, centerX, centerY + 25);
    };

    // Re-draw charts when data changes
    useEffect(() => {
        const timer = setTimeout(() => {
            drawCalorieChart();
            drawTimingChart();
            drawMacroChart();
            drawAccuracyChart();
        }, 100);
        
        return () => clearTimeout(timer);
    }, [dailyLogs, mlData]);

    const exportData = () => {
        const exportData = {
            dailyLogs,
            mlData,
            foodDatabase: foodDatabase.filter(f => f.isShareable),
            quickAdds,
            exportedAt: Date.now(),
            stats
        };
        
        const dataStr = JSON.stringify(exportData, null, 2);
        const dataBlob = new Blob([dataStr], {type: 'application/json'});
        const url = URL.createObjectURL(dataBlob);
        const link = document.createElement('a');
        link.href = url;
        link.download = `calorie-tracker-visualization-data-${new Date().toISOString().split('T')[0]}.json`;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        URL.revokeObjectURL(url);
    };

    return (
        <div className="p-6 max-w-7xl mx-auto">
            <div className="flex justify-between items-center mb-6">
                <h1 className="text-3xl font-bold text-gray-800 flex items-center">
                    <BarChart3 className="w-8 h-8 mr-3 text-indigo-500" />
                    Analytics Dashboard
                </h1>
                <button 
                    onClick={exportData}
                    className="bg-indigo-600 text-white px-4 py-2 rounded-lg hover:bg-indigo-700 transition flex items-center gap-2"
                >
                    <Download className="w-4 h-4" />
                    Export Data
                </button>
            </div>

            {/* Stats Cards */}
            <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-8">
                <div className="bg-gradient-to-br from-blue-500 to-blue-600 text-white p-6 rounded-xl shadow-lg">
                    <div className="text-3xl font-bold">{stats.totalLogs}</div>
                    <div className="text-blue-100">Total Food Entries</div>
                </div>
                <div className="bg-gradient-to-br from-green-500 to-green-600 text-white p-6 rounded-xl shadow-lg">
                    <div className="text-3xl font-bold">{stats.avgCaloriesPerDay}</div>
                    <div className="text-green-100">Avg Calories/Day</div>
                </div>
                <div className="bg-gradient-to-br from-purple-500 to-purple-600 text-white p-6 rounded-xl shadow-lg">
                    <div className="text-3xl font-bold">{stats.accuracy}%</div>
                    <div className="text-purple-100">AI Accuracy</div>
                </div>
                <div className="bg-gradient-to-br from-orange-500 to-orange-600 text-white p-6 rounded-xl shadow-lg">
                    <div className="text-3xl font-bold">{stats.daysTracked}</div>
                    <div className="text-orange-100">Days Tracked</div>
                </div>
            </div>

            {/* Charts Grid */}
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                {/* Daily Calorie Intake */}
                <div className="bg-white p-6 rounded-xl shadow-lg border border-gray-100">
                    <h3 className="text-lg font-semibold text-gray-800 mb-4 flex items-center">
                        <TrendingUp className="w-5 h-5 mr-2 text-blue-500" />
                        Daily Calorie Intake (Last 14 Days)
                    </h3>
                    <canvas 
                        ref={calorieChartRef} 
                        className="w-full h-64 border rounded"
                    />
                </div>

                {/* Meal Timing Patterns */}
                <div className="bg-white p-6 rounded-xl shadow-lg border border-gray-100">
                    <h3 className="text-lg font-semibold text-gray-800 mb-4 flex items-center">
                        <Clock className="w-5 h-5 mr-2 text-green-500" />
                        Meal Timing Patterns
                    </h3>
                    <canvas 
                        ref={timingChartRef} 
                        className="w-full h-64 border rounded"
                    />
                    <div className="flex justify-center gap-4 mt-3 text-xs">
                        {Object.entries(colors).filter(([key]) => ['breakfast', 'lunch', 'dinner', 'snacks'].includes(key)).map(([category, color]) => (
                            <div key={category} className="flex items-center gap-1">
                                <div className="w-3 h-3 rounded" style={{backgroundColor: color}}></div>
                                <span className="capitalize">{category}</span>
                            </div>
                        ))}
                    </div>
                </div>

                {/* Macronutrient Distribution */}
                <div className="bg-white p-6 rounded-xl shadow-lg border border-gray-100">
                    <h3 className="text-lg font-semibold text-gray-800 mb-4 flex items-center">
                        <PieChart className="w-5 h-5 mr-2 text-purple-500" />
                        Macronutrient Distribution
                    </h3>
                    <canvas 
                        ref={macroChartRef} 
                        className="w-full h-64 border rounded"
                    />
                    <div className="flex justify-center gap-4 mt-3 text-xs">
                        <div className="flex items-center gap-1">
                            <div className="w-3 h-3 rounded bg-red-500"></div>
                            <span>Protein</span>
                        </div>
                        <div className="flex items-center gap-1">
                            <div className="w-3 h-3 rounded bg-blue-500"></div>
                            <span>Carbs</span>
                        </div>
                        <div className="flex items-center gap-1">
                            <div className="w-3 h-3 rounded bg-yellow-500"></div>
                            <span>Fat</span>
                        </div>
                    </div>
                </div>

                {/* AI Suggestion Accuracy */}
                <div className="bg-white p-6 rounded-xl shadow-lg border border-gray-100">
                    <h3 className="text-lg font-semibold text-gray-800 mb-4">
                        🎯 AI Suggestion Accuracy
                    </h3>
                    <canvas 
                        ref={accuracyChartRef} 
                        className="w-full h-64 border rounded"
                    />
                </div>
            </div>

            {stats.totalLogs === 0 && (
                <div className="text-center py-12 text-gray-500">
                    <BarChart3 className="w-16 h-16 mx-auto mb-4 opacity-50" />
                    <h3 className="text-xl font-semibold mb-2">No Data Yet</h3>
                    <p>Start logging your meals to see beautiful visualizations here!</p>
                </div>
            )}
        </div>
    );
};

export default DataVisualization;